// w16_names.h -- the Win16 API's export names by module and ordinal, so
// w16 can say what a program imports ("USER.41 CreateWindow"). The table
// (w16_names.c) is GENERATED by tools/gen_w16_ordinals.py.
#ifndef W16_NAMES_H
#define W16_NAMES_H

#include <stdint.h>

struct w16_name {
    uint16_t ordinal;
    int16_t argbytes;      // Pascal argument bytes popped; -1 not Pascal, -2 registers
    uint8_t kind;          // what it is for: w16_kind_names[kind]
    const char *name;
};

// "Dialogs", "Files", "Clipboard"...: what a function is for, from the
// generator's KIND_RULES. w16_kind_other is the kind of an import with
// no entry at all.
extern const char *const w16_kind_names[];
extern const unsigned w16_kind_count, w16_kind_other;

struct w16_name_module {
    const char *module;    // "KERNEL", "USER", "COMMDLG"...
    const struct w16_name *names;   // sorted by ordinal
    unsigned count;
};

extern const struct w16_name_module w16_name_modules[];

// The entry for MODULE.ordinal, or 0. KRNL386 answers as KERNEL.
const struct w16_name *w16_name_lookup(const char *module, unsigned ordinal);

#endif
